CREATE OR REPLACE PROCEDURE sp(para_College VARCHAR2, para_Submission_ID NUMBER, para_Result VARCHAR2, para_Workshop_ID NUMBER) IS
 CURSOR ref_cursor1 IS SELECT * FROM "submission" WHERE "College" = para_College FOR UPDATE;
 CURSOR ref_cursor2 IS SELECT * FROM "Acceptance" WHERE "Submission_ID" > para_Submission_ID FOR UPDATE;
 rec1 ref_cursor1%ROWTYPE;
 rec2 ref_cursor2%ROWTYPE;
 counter INTEGER := 0;
 existing_venue_count INTEGER := 0;
BEGIN
 OPEN ref_cursor1;
 LOOP
  FETCH ref_cursor1 INTO rec1;
  EXIT WHEN ref_cursor1%NOTFOUND;
  DELETE FROM "submission" WHERE CURRENT OF ref_cursor1;
 END LOOP;
 CLOSE ref_cursor1;
 OPEN ref_cursor2;
 LOOP
  FETCH ref_cursor2 INTO rec2;
  EXIT WHEN ref_cursor2%NOTFOUND;
  IF {SLOT_1} THEN
   UPDATE "Acceptance" SET "Result" = {SLOT_2} WHERE CURRENT OF ref_cursor2;
  ELSE
   UPDATE "Acceptance" SET "Result" = {SLOT_3} WHERE CURRENT OF ref_cursor2;
  END IF;
  counter := {SLOT_4};
 END LOOP;
 CLOSE ref_cursor2;
 IF {SLOT_5} THEN
  SELECT COUNT(*) INTO existing_venue_count FROM "workshop" WHERE {SLOT_6};
  IF {SLOT_7} THEN
   INSERT INTO "workshop" ("Workshop_ID") VALUES (para_Workshop_ID);
  END IF;
 END IF;
END;

